def main():
    app = load(APP_ASSET)
    patch = load(PATCH_ASSET)
    if app != patch:
        raise SystemExit("app/patch Ermak diagnostic assets differ before batch2")
    root = deepcopy(app)
    by_id = {s["id"]: s for s in root["scenarios"]}
    missing = sorted(set(ROUTES) - set(by_id))
    if missing:
        raise SystemExit(f"Missing target scenarios: {missing}")
    for sid, route in ROUTES.items():
        apply_route(by_id[sid], **route)
    if len(root["scenarios"]) != 136:
        raise SystemExit("scenario count changed")
    dump(APP_ASSET, root)
    dump(PATCH_ASSET, root)
    if APP_ASSET.read_bytes() != PATCH_ASSET.read_bytes():
        raise SystemExit("app/patch differ after batch2")
    print("ERMAK_P0_BATCH2_DEEPENED=" + ",".join(sorted(ROUTES)))

if __name__ == "__main__":
    main()
